     1→/**
     2→ * RegisterView - 32-register grid visualization with change highlighting
     3→ *
     4→ * Renders 32 general-purpose registers ($0-$31) in a responsive grid.
     5→ * Selectively updates only changed registers per frame for performance.
     6→ * Applies CSS 'changed' class with yellow highlight for modified registers.
     7→ * Register $0 shown with reduced opacity (hardwired to zero).
     8→ *
     9→ * Usage:
    10→ *   const view = new RegisterView(containerElement);
    11→ *   view.render(cpuState);
    12→ */
    13→(function() {
    14→  'use strict';
    15→
    16→  class RegisterView {
    17→    /**
    18→     * Creates a RegisterView instance
    19→     * @param {HTMLElement} container - DOM element to render register grid into
    20→     */
    21→    constructor(container) {
    22→      this.container = container;
    23→      this.registerCells = [];  // Array of 32 DOM elements for O(1) access
    24→      this._previousChanged = [];  // Track previous frame's changes for cleanup
    25→      this._initialized = false;  // Track first render for full update
    26→      this.initializeRegisters();
    27→    }
    28→
    29→    /**
    30→     * Creates the 32 register cells in the DOM
    31→     * Uses DocumentFragment for efficient batch insertion
    32→     */
    33→    initializeRegisters() {
    34→      const fragment = document.createDocumentFragment();
    35→
    36→      for (let i = 0; i < 32; i++) {
    37→        const cell = document.createElement('div');
    38→        cell.className = 'register-cell';
    39→        cell.dataset.register = i;
    40→
    41→        cell.innerHTML = `
    42→          <span class="register-label">$${i}</span>
    43→          <span class="register-value">0x00000000</span>
    44→        `;
    45→
    46→        this.registerCells.push(cell);
    47→        fragment.appendChild(cell);
    48→      }
    49→
    50→      // Single DOM insertion for all register cells
    51→      this.container.appendChild(fragment);
    52→    }
    53→
    54→    /**
    55→     * Renders the current register state
    56→     * Selectively updates only changed registers (not all 32)
    57→     * @param {CPUState} state - Current CPU state with registers and changedRegisters
    58→     */
    59→    render(state) {
    60→      // First render: update all register values
    61→      if (!this._initialized) {
    62→        for (let i = 0; i < 32; i++) {
    63→          const cell = this.registerCells[i];
    64→          const valueEl = cell.querySelector('.register-value');
    65→          const value = state.registers[i];
    66→          valueEl.textContent = '0x' + value.toString(16).toUpperCase().padStart(8, '0');
    67→        }
    68→        this._initialized = true;
    69→        return;
    70→      }
    71→
    72→      // Remove 'changed' class from previous frame's highlighted registers
    73→      this._previousChanged.forEach(index => {
    74→        this.registerCells[index].classList.remove('changed');
    75→      });
    76→
    77→      // Convert Set to Array for iteration
    78→      const changed = Array.from(state.changedRegisters || []);
    79→
    80→      // Update only changed registers
    81→      changed.forEach(index => {
    82→        // Defensive: register $0 should never change due to setRegister protection
    83→        // but handle it gracefully if it somehow appears in changedRegisters
    84→        const cell = this.registerCells[index];
    85→        const valueEl = cell.querySelector('.register-value');
    86→        const value = index === 0 ? 0 : state.registers[index];
    87→
    88→        valueEl.textContent = '0x' + value.toString(16).toUpperCase().padStart(8, '0');
    89→        cell.classList.add('changed');
    90→      });
    91→
    92→      // Store for cleanup on next render
    93→      this._previousChanged = changed;
    94→    }
    95→  }
    96→
    97→  // Export to global scope (vanilla JS pattern)
    98→  if (typeof window !== 'undefined') {
    99→    window.RegisterView = RegisterView;
   100→  } else if (typeof global !== 'undefined') {
   101→    global.RegisterView = RegisterView;
   102→  }
   103→})();
