     1→/**
     2→ * CPUState - Core data structure for CPU simulation
     3→ *
     4→ * Represents the complete state of a pipelined RISC CPU including:
     5→ * - 5 pipeline stages (IF, ID, EX, MEM, WB)
     6→ * - 32 general-purpose registers (register $0 hardwired to zero)
     7→ * - 256-word data memory
     8→ * - Program counter and cycle counters
     9→ * - Visualization metadata for animation framework
    10→ *
    11→ * This class is the foundational unit of the animation system.
    12→ * Every animation frame is a complete, immutable CPUState snapshot.
    13→ */
    14→(function() {
    15→  'use strict';
    16→
    17→  class CPUState {
    18→    constructor() {
    19→      // Pipeline stages with stage-specific fields
    20→      this.pipeline = {
    21→        IF: {
    22→          instruction: null,
    23→          pc: 0,
    24→          active: false
    25→        },
    26→        ID: {
    27→          instruction: null,
    28→          opcode: '',
    29→          rs: 0,
    30→          rt: 0,
    31→          rd: 0,
    32→          imm: 0,
    33→          rsVal: 0,
    34→          rtVal: 0,
    35→          active: false
    36→        },
    37→        EX: {
    38→          aluResult: 0,
    39→          writeData: 0,
    40→          writeReg: 0,
    41→          zero: false,
    42→          active: false
    43→        },
    44→        MEM: {
    45→          memData: 0,
    46→          writeData: 0,
    47→          writeReg: 0,
    48→          memRead: false,
    49→          memWrite: false,
    50→          active: false
    51→        },
    52→        WB: {
    53→          writeData: 0,
    54→          writeReg: 0,
    55→          regWrite: false,
    56→          active: false
    57→        }
    58→      };
    59→
    60→      // Registers: 32 general-purpose registers (Uint32Array for 32-bit unsigned)
    61→      // Register $0 is hardwired to zero
    62→      this.registers = new Uint32Array(32);
    63→
    64→      // Memory: 256-word data memory (1KB for demo purposes)
    65→      this.memory = new Uint32Array(256);
    66→
    67→      // Control state
    68→      this.pc = 0;  // Program counter (word-aligned, increments by 4)
    69→      this.cycleCount = 0;  // Total clock cycles executed
    70→      this.instructionCount = 0;  // Total instructions completed (written back)
    71→
    72→      // Visualization metadata (for Phase 10+ animation)
    73→      this.changedRegisters = new Set();  // Which registers changed this cycle
    74→      this.changedMemory = new Set();  // Which memory addresses changed this cycle
    75→      this.activeStages = new Set();  // Which pipeline stages are active this cycle
    76→      this.hazards = [];  // Active hazards (forward compatibility for Phase 12)
    77→      this.stalls = [];  // Active stalls (forward compatibility for Phase 12)
    78→    }
    79→
    80→    /**
    81→     * Creates a fresh CPUState with all defaults
    82→     * @returns {CPUState} A new CPUState instance
    83→     */
    84→    static createInitial() {
    85→      const state = new CPUState();
    86→      // Explicitly ensure register $0 is zero
    87→      state.registers[0] = 0;
    88→      return state;
    89→    }
    90→
    91→    /**
    92→     * Creates a deep copy of this state
    93→     * Uses structuredClone for complete independence
    94→     * @returns {CPUState} A deep copy of this state
    95→     */
    96→    clone() {
    97→      // structuredClone handles typed arrays and Sets natively
    98→      const cloned = structuredClone(this);
    99→
   100→      // Restore prototype chain (structuredClone creates plain objects)
   101→      Object.setPrototypeOf(cloned, CPUState.prototype);
   102→
   103→      // structuredClone handles Sets correctly, but ensure they're Sets not arrays
   104→      if (Array.isArray(cloned.changedRegisters)) {
   105→        cloned.changedRegisters = new Set(cloned.changedRegisters);
   106→      }
   107→      if (Array.isArray(cloned.changedMemory)) {
   108→        cloned.changedMemory = new Set(cloned.changedMemory);
   109→      }
   110→      if (Array.isArray(cloned.activeStages)) {
   111→        cloned.activeStages = new Set(cloned.activeStages);
   112→      }
   113→
   114→      return cloned;
   115→    }
   116→
   117→    /**
   118→     * Gets a register value
   119→     * Register $0 always returns 0
   120→     * @param {number} index - Register index (0-31)
   121→     * @returns {number} Register value
   122→     */
   123→    getRegister(index) {
   124→      if (index === 0) {
   125→        return 0;  // Register $0 is hardwired to zero
   126→      }
   127→      return this.registers[index];
   128→    }
   129→
   130→    /**
   131→     * Sets a register value
   132→     * Register $0 writes are ignored (hardwired to zero)
   133→     * @param {number} index - Register index (0-31)
   134→     * @param {number} value - Value to set
   135→     */
   136→    setRegister(index, value) {
   137→      if (index === 0) {
   138→        return;  // Cannot write to register $0
   139→      }
   140→
   141→      // Track change only if value actually changed
   142→      const oldValue = this.registers[index];
   143→      if (oldValue !== value) {
   144→        this.registers[index] = value >>> 0;  // Ensure 32-bit unsigned
   145→        this.changedRegisters.add(index);
   146→      }
   147→    }
   148→
   149→    /**
   150→     * Gets a word from memory
   151→     * @param {number} address - Byte address (must be word-aligned)
   152→     * @returns {number} Memory value
   153→     */
   154→    getMemory(address) {
   155→      const wordIndex = address >> 2;  // Convert byte address to word index
   156→      return this.memory[wordIndex];
   157→    }
   158→
   159→    /**
   160→     * Sets a word in memory
   161→     * @param {number} address - Byte address (must be word-aligned)
   162→     * @param {number} value - Value to set
   163→     */
   164→    setMemory(address, value) {
   165→      const wordIndex = address >> 2;  // Convert byte address to word index
   166→
   167→      // Track change only if value actually changed
   168→      const oldValue = this.memory[wordIndex];
   169→      if (oldValue !== value) {
   170→        this.memory[wordIndex] = value >>> 0;  // Ensure 32-bit unsigned
   171→        this.changedMemory.add(address);
   172→      }
   173→    }
   174→  }
   175→
   176→  // Export to global scope (no module bundler - vanilla JS)
   177→  if (typeof window !== 'undefined') {
   178→    window.CPUState = CPUState;
   179→  } else if (typeof global !== 'undefined') {
   180→    global.CPUState = CPUState;
   181→  }
   182→})();
