     1→/**
     2→ * InstructionSet - RISC instruction definitions for CPU simulation
     3→ *
     4→ * Defines 8 core RISC instructions with their types, field mappings, and execute functions.
     5→ * Instruction types: R (register), I (immediate), S (store), B (branch), J (jump)
     6→ *
     7→ * Instructions:
     8→ * - ADD, SUB (R-type)
     9→ * - ADDI, LW (I-type)
    10→ * - SW (S-type)
    11→ * - BEQ (B-type)
    12→ * - J (J-type)
    13→ * - NOP (special)
    14→ */
    15→(function() {
    16→  'use strict';
    17→
    18→  /**
    19→   * Instruction definitions with execute functions
    20→   * Execute functions compute results but do NOT mutate state
    21→   */
    22→  const INSTRUCTIONS = {
    23→    ADD: {
    24→      mnemonic: 'ADD',
    25→      type: 'R',
    26→      description: 'Add two registers',
    27→      fields: {
    28→        rs: true,   // Source register 1
    29→        rt: true,   // Source register 2
    30→        rd: true,   // Destination register
    31→        immediate: false
    32→      },
    33→      execute: function(state, instruction) {
    34→        const rsVal = state.getRegister(instruction.rs);
    35→        const rtVal = state.getRegister(instruction.rt);
    36→        const result = (rsVal + rtVal) >>> 0;  // 32-bit unsigned wrapping
    37→        return {
    38→          aluResult: result,
    39→          writeReg: instruction.rd,
    40→          writeData: result
    41→        };
    42→      }
    43→    },
    44→
    45→    SUB: {
    46→      mnemonic: 'SUB',
    47→      type: 'R',
    48→      description: 'Subtract two registers',
    49→      fields: {
    50→        rs: true,
    51→        rt: true,
    52→        rd: true,
    53→        immediate: false
    54→      },
    55→      execute: function(state, instruction) {
    56→        const rsVal = state.getRegister(instruction.rs);
    57→        const rtVal = state.getRegister(instruction.rt);
    58→        const result = (rsVal - rtVal) >>> 0;  // 32-bit unsigned wrapping
    59→        return {
    60→          aluResult: result,
    61→          writeReg: instruction.rd,
    62→          writeData: result
    63→        };
    64→      }
    65→    },
    66→
    67→    ADDI: {
    68→      mnemonic: 'ADDI',
    69→      type: 'I',
    70→      description: 'Add immediate to register',
    71→      fields: {
    72→        rs: true,
    73→        rt: true,   // ADDI writes to rt (not rd) in MIPS
    74→        rd: false,
    75→        immediate: true
    76→      },
    77→      execute: function(state, instruction) {
    78→        const rsVal = state.getRegister(instruction.rs);
    79→        const result = (rsVal + instruction.immediate) >>> 0;  // 32-bit unsigned wrapping
    80→        return {
    81→          aluResult: result,
    82→          writeReg: instruction.rt,
    83→          writeData: result
    84→        };
    85→      }
    86→    },
    87→
    88→    LW: {
    89→      mnemonic: 'LW',
    90→      type: 'I',
    91→      description: 'Load word from memory',
    92→      fields: {
    93→        rs: true,   // Base address register
    94→        rt: true,   // Destination register
    95→        rd: false,
    96→        immediate: true  // Offset
    97→      },
    98→      execute: function(state, instruction) {
    99→        const rsVal = state.getRegister(instruction.rs);
   100→        const address = (rsVal + instruction.immediate) >>> 0;
   101→        return {
   102→          aluResult: address,
   103→          writeReg: instruction.rt,
   104→          memRead: true
   105→        };
   106→      }
   107→    },
   108→
   109→    SW: {
   110→      mnemonic: 'SW',
   111→      type: 'S',
   112→      description: 'Store word to memory',
   113→      fields: {
   114→        rs: true,   // Base address register
   115→        rt: true,   // Source data register
   116→        rd: false,
   117→        immediate: true  // Offset
   118→      },
   119→      execute: function(state, instruction) {
   120→        const rsVal = state.getRegister(instruction.rs);
   121→        const rtVal = state.getRegister(instruction.rt);
   122→        const address = (rsVal + instruction.immediate) >>> 0;
   123→        return {
   124→          aluResult: address,
   125→          writeData: rtVal,
   126→          memWrite: true
   127→        };
   128→      }
   129→    },
   130→
   131→    BEQ: {
   132→      mnemonic: 'BEQ',
   133→      type: 'B',
   134→      description: 'Branch if equal',
   135→      fields: {
   136→        rs: true,
   137→        rt: true,
   138→        rd: false,
   139→        immediate: true  // Branch offset (in instructions, not bytes)
   140→      },
   141→      execute: function(state, instruction) {
   142→        const rsVal = state.getRegister(instruction.rs);
   143→        const rtVal = state.getRegister(instruction.rt);
   144→        const zero = (rsVal === rtVal);
   145→        const branchTarget = (state.pc + instruction.immediate * 4) >>> 0;
   146→        return {
   147→          zero: zero,
   148→          branchTarget: branchTarget
   149→        };
   150→      }
   151→    },
   152→
   153→    J: {
   154→      mnemonic: 'J',
   155→      type: 'J',
   156→      description: 'Jump to address',
   157→      fields: {
   158→        rs: false,
   159→        rt: false,
   160→        rd: false,
   161→        immediate: true  // Jump target (word address)
   162→      },
   163→      execute: function(state, instruction) {
   164→        const jumpTarget = (instruction.immediate * 4) >>> 0;
   165→        return {
   166→          jumpTarget: jumpTarget
   167→        };
   168→      }
   169→    },
   170→
   171→    NOP: {
   172→      mnemonic: 'NOP',
   173→      type: 'NOP',
   174→      description: 'No operation',
   175→      fields: {
   176→        rs: false,
   177→        rt: false,
   178→        rd: false,
   179→        immediate: false
   180→      },
   181→      execute: function(state, instruction) {
   182→        return {};  // No effect
   183→      }
   184→    }
   185→  };
   186→
   187→  /**
   188→   * InstructionSet class with helper methods
   189→   */
   190→  class InstructionSet {
   191→    /**
   192→     * Gets instruction definition by mnemonic
   193→     * @param {string} mnemonic - Instruction mnemonic (e.g., 'ADD')
   194→     * @returns {object|null} Instruction definition or null if not found
   195→     */
   196→    static get(mnemonic) {
   197→      return INSTRUCTIONS[mnemonic.toUpperCase()] || null;
   198→    }
   199→
   200→    /**
   201→     * Checks if instruction is a memory instruction
   202→     * @param {string} mnemonic - Instruction mnemonic
   203→     * @returns {boolean} True if LW or SW
   204→     */
   205→    static isMemoryInstruction(mnemonic) {
   206→      const upper = mnemonic.toUpperCase();
   207→      return upper === 'LW' || upper === 'SW';
   208→    }
   209→
   210→    /**
   211→     * Checks if instruction is a branch/jump instruction
   212→     * @param {string} mnemonic - Instruction mnemonic
   213→     * @returns {boolean} True if BEQ or J
   214→     */
   215→    static isBranch(mnemonic) {
   216→      const upper = mnemonic.toUpperCase();
   217→      return upper === 'BEQ' || upper === 'J';
   218→    }
   219→
   220→    /**
   221→     * Checks if instruction writes to a register
   222→     * @param {string} mnemonic - Instruction mnemonic
   223→     * @returns {boolean} True if instruction writes back to register file
   224→     */
   225→    static writesToRegister(mnemonic) {
   226→      const upper = mnemonic.toUpperCase();
   227→      // ADD, SUB, ADDI, LW write to registers
   228→      // SW, BEQ, J, NOP do not
   229→      return upper === 'ADD' || upper === 'SUB' || upper === 'ADDI' || upper === 'LW';
   230→    }
   231→
   232→    /**
   233→     * Creates a concrete instruction object from mnemonic and field values
   234→     * @param {string} mnemonic - Instruction mnemonic
   235→     * @param {object} fields - Field values { rs, rt, rd, immediate }
   236→     * @returns {object} Concrete instruction object
   237→     */
   238→    static createInstruction(mnemonic, fields = {}) {
   239→      const def = InstructionSet.get(mnemonic);
   240→      if (!def) {
   241→        throw new Error(`Unknown instruction: ${mnemonic}`);
   242→      }
   243→
   244→      return {
   245→        mnemonic: def.mnemonic,
   246→        type: def.type,
   247→        rs: fields.rs || 0,
   248→        rt: fields.rt || 0,
   249→        rd: fields.rd || 0,
   250→        immediate: fields.immediate || 0
   251→      };
   252→    }
   253→
   254→    /**
   255→     * Gets all instruction mnemonics
   256→     * @returns {string[]} Array of instruction mnemonics
   257→     */
   258→    static getAllMnemonics() {
   259→      return Object.keys(INSTRUCTIONS);
   260→    }
   261→
   262→    /**
   263→     * Gets all instruction definitions
   264→     * @returns {object} Map of mnemonic -> definition
   265→     */
   266→    static getAll() {
   267→      return { ...INSTRUCTIONS };
   268→    }
   269→  }
   270→
   271→  // Export to global scope (no module bundler - vanilla JS)
   272→  if (typeof window !== 'undefined') {
   273→    window.InstructionSet = InstructionSet;
   274→  } else if (typeof global !== 'undefined') {
   275→    global.InstructionSet = InstructionSet;
   276→  }
   277→})();
