}

.memory-row {
  transition: background-color 0.3s ease-out;
}

.memory-row.changed {
  background-color: var(--color-highlight-yellow);
}

.memory-address,
.memory-value {
  font-family: var(--font-mono);
  letter-spacing: 0.5px;
}

.empty-state {
  text-align: center;
  padding: 24px;
  color: var(--color-text-muted);
  font-style: italic;
}

/* ============================================
 * INSTRUCTION VIEW
 * ============================================ */

.instruction-view {
  padding: 16px;
}

.instruction-view h3 {
  font-size: var(--text-md);
  margin-bottom: 12px;
  color: var(--color-text-heading);
}

.instruction-display {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: 4px;
  padding: 16px;
}

.instruction-placeholder {
  color: var(--color-text-muted);
  font-style: italic;
  text-align: center;
  padding: 12px;
}

.instruction-mnemonic {
  margin-bottom: 12px;
  font-size: 16px;
}

.instruction-mnemonic .value {
  font-weight: bold;
  font-family: var(--font-mono);
  margin-left: 8px;
}

.instruction-fields {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 12px;
}

.field {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  background: var(--color-surface-alt);
  border-radius: 4px;
  font-size: 14px;
}

.field-name {
  font-weight: bold;
  color: var(--color-text-muted);
}

.field-value {
  font-family: var(--font-mono);
  color: var(--color-text);
}

.instruction-comment {
  font-style: italic;
  color: var(--color-text-muted);
  font-size: 14px;
  margin-top: 8px;
}

.instruction-comment .value {
  margin-left: 8px;
}

/* ============================================
 * INSTRUCTION LIST
 * ============================================ */

.instruction-list-container {
  max-height: 400px;
  overflow-y: auto;
  padding: 16px;
  border: 1px solid var(--color-border);
  border-radius: 4px;
}

.instruction-list-container h3 {
  font-size: var(--text-md);
  margin-bottom: 12px;
  color: var(--color-text-heading);
}

.instruction-list {
  list-style-position: inside;
  margin: 0;
  padding: 0;
}

.instruction-item {
  padding: 10px 12px;
  border-bottom: 1px solid var(--color-border);
  transition: background-color 0.2s ease;
  display: flex;
  gap: 8px;
  align-items: baseline;
}

.instruction-item:last-child {
  border-bottom: none;
}

.instruction-item.clickable {
  cursor: pointer;
}

.instruction-item.clickable:hover {
  background: var(--color-surface-alt);
}

.instruction-item.active {
  background: #E8F5E9;  /* Light green - matches IF stage color */
  border-left: 4px solid var(--stage-if-color);
  padding-left: 8px;
}

.instruction-item:focus-visible {
  outline: 2px solid var(--stage-if-color);
  outline-offset: -2px;
}

.inst-mnemonic {
  font-weight: bold;
  font-family: var(--font-mono);
  min-width: 60px;
}

.inst-operands {
  font-family: var(--font-mono);
  color: var(--color-text);
}

.inst-comment {
  font-style: italic;
  color: var(--color-text-muted);
  font-size: 13px;
  margin-left: auto;
}

/* ============================================
 * ACCESSIBILITY - REDUCED MOTION
 * ============================================ */

@media (prefers-reduced-motion: reduce) {
  .memory-row,
  .instruction-item {
    transition: none;
  }
}

